using System;
using System.Collections.Generic;
using Newtonsoft.Json;
using Newtonsoft.Json.Linq;
public class CPHInline {
 static readonly object Gate=String.Intern("streamercompanion:named-timers:state:v1");
 const string StateKey="portable.timers.state",QueueKey="managedLanguageRedemptionsJson",ActiveKey="managedLanguageActive";
 string Arg(string key){try{return args.ContainsKey(key)&&args[key]!=null?args[key].ToString().Trim():"";}catch{return "";}}
 string Read(string key){try{return CPH.GetGlobalVar<string>(key,true)??"";}catch{return "";}}
 protected virtual long NowSeconds(){return DateTimeOffset.UtcNow.ToUnixTimeSeconds();}
 protected virtual long NowMilliseconds(){return DateTimeOffset.UtcNow.ToUnixTimeMilliseconds();}
 void PrepareChat(string message){CPH.SetArgument("chatMessage",message??"");CPH.SetArgument("chatReplyId","");CPH.SetArgument("chatReplyUser","");CPH.SetArgument("chatIsReply",false);CPH.SetArgument("chatTargets","all");CPH.SetArgument("chatShouldSend",true);}
 string Title(string input){string lower=(input??"").Trim().ToLowerInvariant(),result="";foreach(char c in lower){bool letter=c>='a'&&c<='z',number=c>='0'&&c<='9';if(letter||number||c=='_'||c=='-')result+=c;else if(c==' ')result+="_";}return String.IsNullOrWhiteSpace(result)?"default":result;}
 string Duration(long total){if(total<0)total=0;long hours=total/3600,minutes=(total%3600)/60,seconds=total%60;if(hours>0)return hours+"h "+minutes+"m "+seconds+"s";if(minutes>0)return minutes+"m "+seconds+"s";return seconds+"s";}
 JArray Array(string key){try{return JArray.Parse(Read(key));}catch{return new JArray();}}
 bool Add(){string raw=Arg("timerSeconds");int seconds;if(String.IsNullOrWhiteSpace(raw)){PrepareChat("Timer error: missing timer duration.");return true;}if(!Int32.TryParse(raw,out seconds)){PrepareChat("Timer error: '"+raw+"' is not a valid number of seconds.");return true;}if(seconds<=0){PrepareChat("Timer error: duration must be more than 0 seconds.");return true;}string title=Title(Arg("timerTitle")),key="timer_end_"+title;long now=NowSeconds(),current=0;Int64.TryParse(Read(key),out current);bool active=current>now;long end=active?current+seconds:now+seconds;CPH.SetGlobalVar(key,end.ToString(),true);PrepareChat(active?"Added "+Duration(seconds)+" to the "+title+" timer. New remaining time: "+Duration(end-now)+".":"Started "+title+" timer for "+Duration(end-now)+".");return true;}
 bool Command(){CPH.SetArgument("timerCommandValid",false);string input=Arg("rawInput");if(String.IsNullOrWhiteSpace(input)){PrepareChat("Usage: !timer <seconds> <title>. Example: !timer 600 hydration");return true;}string[] parts=input.Split(new[]{' '},2,StringSplitOptions.RemoveEmptyEntries);int seconds;if(parts.Length<1||!Int32.TryParse(parts[0],out seconds)){PrepareChat("Timer error: '"+(parts.Length>0?parts[0]:"")+"' is not a valid number of seconds.");return true;}if(seconds<=0){PrepareChat("Timer error: duration must be more than 0 seconds.");return true;}CPH.SetArgument("timerSeconds",seconds.ToString());CPH.SetArgument("timerTitle",parts.Length>1&&!String.IsNullOrWhiteSpace(parts[1])?parts[1].Trim():"default");CPH.SetArgument("timerCommandValid",true);return true;}
 bool Check(){long now=NowSeconds();foreach(var global in CPH.GetGlobalVarValues(true)){string name=global.VariableName??"";if(!name.StartsWith("timer_end_",StringComparison.Ordinal))continue;string title=name.Substring("timer_end_".Length);if(title=="german"||title=="french"||title=="dutch")continue;long end;if(!Int64.TryParse(global.Value==null?"":global.Value.ToString(),out end)||end<=0||now<end)continue;PrepareChat(title+" timer is done!");CPH.SetGlobalVar(name,"0",true);}return true;}
 bool Publish(JObject phoneResults=null){long now=NowSeconds();JArray timers=new JArray();foreach(var global in CPH.GetGlobalVarValues(true)){string name=global.VariableName??"";if(!name.StartsWith("timer_end_",StringComparison.Ordinal)||global.Value==null)continue;long end;if(!Int64.TryParse(global.Value.ToString(),out end)||end<=now)continue;timers.Add(new JObject{{"id",name},{"title",name.Substring("timer_end_".Length)},{"endTimeSeconds",end}});}long revision=1;try{revision=((long?)JObject.Parse(Read(StateKey))["revision"]??0)+1;}catch{}JObject envelope=new JObject{{"schemaVersion",1},{"feature","timers"},{"type","state"},{"revision",revision},{"payload",new JObject{{"timers",timers},{"serverTimeMs",NowMilliseconds()}}}};var payload=(JObject)envelope["payload"];payload["phoneDeckVersion"]=1;payload["phoneDeckResults"]=phoneResults??PhoneResults();payload["phoneDeck"]=new JObject{{"activeCount",timers.Count},{"summary",String.Join(" | ",System.Linq.Enumerable.Select(timers,t=>(string)t["title"]+": "+Duration((long)t["endTimeSeconds"]-now)))}};string json=envelope.ToString(Formatting.None);CPH.SetGlobalVar(StateKey,json,true);try{CPH.WebsocketBroadcastJson(json);}catch{}return true;}
 void ResetLanguages(IEnumerable<string> names,string active,long end){HashSet<string> all=new HashSet<string>(StringComparer.Ordinal){"dutch","french","german"};foreach(string name in names)if(!String.IsNullOrWhiteSpace(name))all.Add(Title(name));string previous=Title(Read(ActiveKey));if(previous!="default")all.Add(previous);foreach(string name in all)CPH.SetGlobalVar("timer_end_"+name,(name==active?end:0).ToString(),true);}
 bool QueueLanguage(){string language=Title(Arg("language")),raw=Arg("durationSeconds");int seconds=300;if(!String.IsNullOrWhiteSpace(raw)&&(!Int32.TryParse(raw,out seconds)||seconds<=0)){PrepareChat("Language timer error: duration must be more than 0 seconds.");return true;}JArray queue=Array(QueueKey);long now=NowSeconds(),tail=now;List<string> names=new List<string>();foreach(JObject item in queue){tail=Math.Max(tail,(long?)item["dueAt"]??now);names.Add((string)item["language"]??"");}long starts=tail,due=starts+seconds;queue.Add(new JObject{{"rewardId",Arg("rewardId")},{"redemptionId",Arg("redemptionId")},{"language",language},{"startsAt",starts},{"dueAt",due},{"userName",Arg("user")}});CPH.SetGlobalVar(QueueKey,queue.ToString(Formatting.None),true);names.Add(language);if(starts<=now){ResetLanguages(names,language,due);CPH.SetGlobalVar(ActiveKey,language,true);PrepareChat(language+" timer starts now!");}else PrepareChat(language+" is queued and will start after the current language timer.");CPH.SetArgument("languageStartsAt",starts);CPH.SetArgument("languageDueAt",due);return true;}
 bool CheckLanguages(){JArray queue=Array(QueueKey),keep=new JArray();long now=NowSeconds();List<string> names=new List<string>();foreach(JObject item in queue){string language=(string)item["language"]??"";names.Add(language);long due=(long?)item["dueAt"]??0;if(due>now){keep.Add(item);continue;}string reward=(string)item["rewardId"]??"",redemption=(string)item["redemptionId"]??"";bool complete=String.IsNullOrWhiteSpace(reward)||String.IsNullOrWhiteSpace(redemption);if(!complete)try{complete=CPH.TwitchRedemptionFulfill(reward,redemption);}catch{}if(!complete)keep.Add(item);}CPH.SetGlobalVar(QueueKey,keep.ToString(Formatting.None),true);string active="";long activeEnd=0;foreach(JObject item in keep){long due=(long?)item["dueAt"]??0,start=(long?)item["startsAt"]??Math.Max(0,due-300);if(start<=now&&due>now){active=(string)item["language"]??"";activeEnd=due;break;}}string previous=Read(ActiveKey);ResetLanguages(names,active,activeEnd);CPH.SetGlobalVar(ActiveKey,active,true);if(active!=previous){if(!String.IsNullOrWhiteSpace(active))PrepareChat(active+" timer starts now!");else if(!String.IsNullOrWhiteSpace(previous))PrepareChat(previous+" timer is done!");}return true;}

 JObject PhoneResults(){try{return (JObject)(JObject.Parse(Read(StateKey))["payload"]?["phoneDeckResults"]??new JObject()).DeepClone();}catch{return new JObject();}}
 bool PhoneAdd(){string id=Arg("requestId");if(id==""||id.Length>128)throw new Exception("A valid request ID is required.");var results=PhoneResults();if(results[id]!=null)return true;int seconds;string title=Title(Arg("timerTitle"));bool valid=Int32.TryParse(Arg("timerSeconds"),out seconds)&&seconds>0&&seconds<=604800&&Arg("timerTitle").Length>0&&Arg("timerTitle").Length<=80&&title!="german"&&title!="french"&&title!="dutch";while(results.Count>=32)System.Linq.Enumerable.First(results.Properties()).Remove();results[id]=new JObject{{"status",valid?"running":"error"}};Publish(results);if(!valid)return true;try{Add();results[id]["status"]="completed";Publish(results);}catch{CPH.LogError("[named-timers] Phone operation outcome is unknown; no replay was attempted.");}return true;}
 public bool Execute(){lock(Gate){return ExecuteLocked();}}
 bool ExecuteLocked(){CPH.SetArgument("chatShouldSend",false);try{string mode=Arg("namedTimersMode");if(mode=="phone-add")return PhoneAdd();if(mode=="add")return Add();if(mode=="check")return Check();if(mode=="command")return Command();if(mode=="language-queue")return QueueLanguage();if(mode=="language-check")return CheckLanguages();if(mode=="publish"||mode=="initialize"||mode=="health")return Publish();return false;}catch(Exception ex){CPH.LogError("[named-timers] "+ex);return false;}}
}
